import { ReactNode, FC } from 'react';

interface NavBarProps {
    /** 标题 */
    title?: ReactNode;
    /** 左侧内容 */
    left?: ReactNode;
    /** 右侧内容 */
    right?: ReactNode;
    /** 是否显示返回按钮 */
    showBack?: boolean;
    /** 返回按钮点击 */
    onBack?: () => void;
    /** 是否固定在顶部 */
    fixed?: boolean;
    /** 是否显示下边框 */
    bordered?: boolean;
    /** 是否沉浸式（透明背景） */
    transparent?: boolean;
    /** 背景色 */
    backgroundColor?: string;
    /** 文字颜色 */
    color?: string;
    /** 占位元素（fixed 时使用） */
    placeholder?: boolean;
    /** 自定义类名 */
    className?: string;
}

declare const NavBar: FC<NavBarProps>;

export { NavBar, NavBar as default };
export type { NavBarProps };
